    public void handle( CreateClaimEvent event) {
	    LOGGER.info("handling CreateClaimEvent - " + event );
	    Claim entity = new Claim();
            entity.setClaimId( event.getClaimId() );
            entity.setClaimNumber( event.getClaimNumber() );
            entity.setNoticeDate( event.getNoticeDate() );
            entity.setLossDate( event.getLossDate() );
            entity.setReportedBy( event.getReportedBy() );
            entity.setStatus( event.getStatus() );
            entity.setLossCause( event.getLossCause() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllClaim( entity );
    }

